INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l09','a large crowd of','',NULL,'/ə lɑːrdʒ kraʊd əv/','A large crowd of people gathered.','一大群人聚集起来。','A large crowd of fans waited outside.','一大群粉丝在外面等着。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l09','in … minutes'' time','',NULL,'/ɪn ˈmɪnɪts taɪm/','The clock would strike twelve in twenty minutes'' time.','再过二十分钟大钟就会敲十二点。','The bus will come in five minutes'' time.','公交车五分钟后就到。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l09','at that moment','',NULL,'/æt ðæt ˈmoʊmənt/','At that moment, someone shouted.','就在那一刻,有人喊了起来。','At that moment, the lights went out.','就在那一刻,灯灭了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp1','choice','{"stem":"\"The clock stopped ___ five to twelve.\"(具体钟点)","options":["at","by","in","on"],"answer_index":0,"explanation_cn":"具体钟点前用 at。✓ The clock stopped at five to twelve.（at + 几点几分）"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp1','choice','{"stem":"\"___ that moment, everybody laughed.\"","options":["In","At","On","During"],"answer_index":1,"explanation_cn":"at that moment(在那一刻)是固定说法,时刻点用 at。✓ At that moment, everybody laughed."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp2','choice','{"stem":"\"The war ended ___ 1945.\"(年份)","options":["by","on","in","at"],"answer_index":2,"explanation_cn":"年份前用 in。✓ The war ended in 1945."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp2','choice','{"stem":"\"It is very cold ___ winter.\"(季节)","options":["in","at","on","during"],"answer_index":0,"explanation_cn":"季节前用 in。✓ in winter / in summer."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp3','choice','{"stem":"\"I get up early ___ the morning.\"","options":["on","in","at","by"],"answer_index":1,"explanation_cn":"\"上午、下午、晚上\"(the morning/afternoon/evening)前用 in。✓ in the morning."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp3','choice','{"stem":"\"上午 / 下午 / 晚上(the morning/afternoon/evening)\"前一般用:","options":["on","during","at","in"],"answer_index":3,"explanation_cn":"in the morning / in the afternoon / in the evening 都用 in(这是要记住的固定搭配)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp4','choice','{"stem":"\"We went to the Town Hall ___ Wednesday.\"(星期)","options":["by","on","in","at"],"answer_index":1,"explanation_cn":"星期几前用 on。✓ We went to the Town Hall on Wednesday."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp4','choice','{"stem":"\"My birthday is ___ November 7th.\"(具体日期)","options":["on","in","at","of"],"answer_index":0,"explanation_cn":"具体日期(几月几号)前用 on。✓ My birthday is on November 7th."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp4','choice','{"stem":"\"具体某一天(星期几 / 几月几号)\"前用:","options":["in","at","by","on"],"answer_index":3,"explanation_cn":"具体某一天——星期几、几月几号、生日那天——前面都用 on。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp5','choice','{"stem":"\"The train is leaving ___ ten minutes.\"(十分钟后)","options":["after","in","on","at"],"answer_index":1,"explanation_cn":"\"再过十分钟 / 十分钟后\"这种\"一段时间之后\"用 in(常见于将来)。✓ The train is leaving in ten minutes."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp5','choice','{"stem":"\"The clock would strike twelve ___ twenty minutes'' time.\"(20分钟后)","options":["at","on","for","in"],"answer_index":3,"explanation_cn":"in twenty minutes'' time = 20分钟之后,同样用 in 表示\"…之后\"。✓"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp6','choice','{"stem":"选出正确的一句:","options":["I saw him on Monday morning.","I saw him in Monday morning.","I saw him on the Monday in morning.","I saw him at Monday morning."],"answer_index":0,"explanation_cn":"虽然\"上午\"单说用 in the morning,但一旦点明\"具体某天的上午\"(Monday morning),就用 on。✓ on Monday morning."}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp6','choice','{"stem":"只说\"十月\"(不带具体某天)用:","options":["at October","on October","on October day","in October"],"answer_index":3,"explanation_cn":"只说月份(不带具体某天)用 in。✓ in October.（若是 10 月 5 号则说 on October 5th）"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp6','choice','{"stem":"\"在晚上\"一般说 ___;但\"在夜里\"用 at night。","options":["on evening","on the evening","in the evening","at the evening"],"answer_index":2,"explanation_cn":"\"在晚上\"固定说 in the evening;\"在夜里\"才用 at night。✓"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp7','choice','{"stem":"\"He got married ___ twenty.\"(在20岁时)","options":["at","on","by","in"],"answer_index":0,"explanation_cn":"表示年龄\"在几岁时\"用 at。✓ He got married at twenty. / at the age of twenty."}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp7','choice','{"stem":"\"The shops are open ___ 9 ___ 5.\"(从9点到5点)","options":["in … to","at … at","from … till","on … on"],"answer_index":2,"explanation_cn":"\"从…到…\"用 from … till/to。✓ The shops are open from 9 till 5."}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp8','choice','{"stem":"a large crowd of people 的意思是:","options":["一小队人","一大群人","几个人","没有人"],"answer_index":1,"explanation_cn":"a large crowd of people = 一大群人。✓ A large crowd of people gathered."}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',5,'am2_l09_gp8','choice','{"stem":"in twenty minutes'' time 的意思是:","options":["20分钟以前","20分钟之内","正好20分钟","20分钟之后"],"answer_index":3,"explanation_cn":"in twenty minutes'' time = 20分钟之后。✓ The clock would strike in twenty minutes'' time."}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"美语里\"在周末\"说:","options":["at the weekend","in the weekend","on the weekend","by the weekend"],"answer_index":2,"explanation_cn":"美语\"在周末\"说 on the weekend;英式说 at the weekend。✓ I relax on the weekend."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"美语里\"人行道\"用:","options":["sidewalk","footpath","roadside","pavement"],"answer_index":0,"explanation_cn":"美语\"人行道\"用 sidewalk;英式用 pavement。✓ walk on the sidewalk."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"美语里\"排队(的队伍)\"用:","options":["row","line","queue","file"],"answer_index":1,"explanation_cn":"美语\"排队的队伍\"用 line(stand in line);英式用 queue。✓ People stood in a long line."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"a large crowd of 的意思是:","options":["一大群","一小撮","没有","一对"],"answer_index":0,"explanation_cn":"a large crowd of = 一大群。✓ a large crowd of people."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"in twenty minutes'' time 的意思是:","options":["20分钟以前","20分钟之内","20分钟之后","整整20分钟"],"answer_index":2,"explanation_cn":"in twenty minutes'' time = 20分钟之后。✓"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',6,NULL,'choice','{"stem":"at that moment 的意思是:","options":["从那以后","过了一会儿","在这之前","就在那一刻"],"answer_index":3,"explanation_cn":"at that moment = 就在那一刻。✓ At that moment, someone shouted."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',7,NULL,'cloze','{"stem":"第 1 空","context":"We went to the Town Hall ___1___ New Year''s Eve. A big crowd gathered ___2___ the evening. The clock would strike twelve ___3___ a few minutes. But ___4___ five to twelve, it suddenly stopped!","blank_no":1,"options":["on","in","at","by"],"answer_index":0,"explanation_cn":"New Year''s Eve 是具体某一天,用 on。✓ on New Year''s Eve."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',7,NULL,'cloze','{"stem":"第 2 空","context":"We went to the Town Hall ___1___ New Year''s Eve. A big crowd gathered ___2___ the evening. The clock would strike twelve ___3___ a few minutes. But ___4___ five to twelve, it suddenly stopped!","blank_no":2,"options":["in","on","at","during"],"answer_index":0,"explanation_cn":"\"在晚上\"用 in the evening。✓ gathered in the evening."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',7,NULL,'cloze','{"stem":"第 3 空","context":"We went to the Town Hall ___1___ New Year''s Eve. A big crowd gathered ___2___ the evening. The clock would strike twelve ___3___ a few minutes. But ___4___ five to twelve, it suddenly stopped!","blank_no":3,"options":["in","on","after","at"],"answer_index":0,"explanation_cn":"\"再过几分钟 / 几分钟后\"用 in。✓ in a few minutes."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',7,NULL,'cloze','{"stem":"第 4 空","context":"We went to the Town Hall ___1___ New Year''s Eve. A big crowd gathered ___2___ the evening. The clock would strike twelve ___3___ a few minutes. But ___4___ five to twelve, it suddenly stopped!","blank_no":4,"options":["at","in","on","by"],"answer_index":0,"explanation_cn":"具体钟点\"差5分12点\"用 at。✓ at five to twelve."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',8,NULL,'choice','{"stem":"When did they go to the Town Hall?","options":["On a Monday morning","In the summer","On New Year''s Eve","On New Year''s Day"],"answer_index":2,"explanation_cn":"课文说 It was New Year''s Eve… we went to the Town Hall,他们是除夕夜去的。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',8,NULL,'choice','{"stem":"What happened at five to twelve?","options":["The clock stopped","It started to rain","The crowd went home","The clock struck twelve"],"answer_index":0,"explanation_cn":"课文说 at five to twelve, the big clock suddenly stopped,差5分12点时大钟停了。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',8,NULL,'choice','{"stem":"What did everybody do at the end?","options":["They fixed the clock","They went home","They shouted angrily","They laughed and sang"],"answer_index":3,"explanation_cn":"课文结尾 Everybody began to laugh… and started to sing,大家笑着唱了起来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',9,NULL,'choice','{"stem":"你想约朋友\"我们晚上7点见\"(具体钟点):","options":["Let''s meet at seven on the evening.","Let''s meet at seven in the evening.","Let''s meet in seven at the evening.","Let''s meet on seven in evening."],"answer_index":1,"explanation_cn":"钟点用 at(at seven),\"晚上\"用 in the evening。✓ Let''s meet at seven in the evening. 场合:和朋友约时间见面。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',9,NULL,'choice','{"stem":"你想说\"我的生日在10月1号\":","options":["My birthday is in October 1st.","My birthday is at October 1st.","My birthday is at the October 1st.","My birthday is on October 1st."],"answer_index":3,"explanation_cn":"具体日期(10月1号)用 on。✓ My birthday is on October 1st. 场合:告诉别人你的生日。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',9,NULL,'choice','{"stem":"你想说\"火车十分钟后到\"(将来的''…之后''):","options":["The train will arrive at ten minutes.","The train will arrive after ten minutes later.","The train will arrive in ten minutes.","The train will arrive on ten minutes."],"answer_index":2,"explanation_cn":"\"十分钟后\"这种\"一段时间之后\"用 in。✓ The train will arrive in ten minutes. 场合:告诉别人火车还有多久到。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"crowd 的意思是:","options":["吵闹声","王冠","人群","云"],"answer_index":2,"explanation_cn":"crowd = 人群。✓ A huge crowd gathered under the clock."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"refuse 的意思是:","options":["接受","拒绝","害怕","欢迎"],"answer_index":1,"explanation_cn":"refuse = 拒绝。✓ The clock refused to welcome the New Year."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"\"The movie starts ___ 8 o''clock.\"(钟点)","options":["at","by","on","in"],"answer_index":0,"explanation_cn":"具体钟点用 at。✓ The movie starts at 8 o''clock."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"\"It often snows ___ January.\"(只说月份)","options":["at","on","in","during"],"answer_index":2,"explanation_cn":"只说月份(January)用 in。✓ It often snows in January."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"\"See you on Monday!\" 的意思是:","options":["上午见","月底见","一会儿见","星期一见"],"answer_index":3,"explanation_cn":"See you on Monday = 星期一见(on + 星期几)。场合:和人道别、约下次见面。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"\"I''ll be back in five minutes.\" 的意思是:","options":["我五点回来","我已经回来五分钟了","我五分钟后回来","我回来待五分钟"],"answer_index":2,"explanation_cn":"I''ll be back in five minutes = 我五分钟后回来(in + 一段时间 = …之后)。场合:临时离开告诉别人多久回来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"Why is it called \"a cold welcome\"?","options":["Because the clock stopped and refused to welcome the New Year","Because it was snowing hard","Because the crowd was rude","Because nobody came"],"answer_index":0,"passage":"It was New Year''s Eve, and that year it fell on the weekend. On Saturday night, my friends and I went to the old Town Hall. A huge crowd gathered on the sidewalk under the big clock. People stood in a long line, waiting to welcome the New Year. The clock would strike twelve at midnight, in just a few minutes. But at five to twelve, the big clock suddenly stopped! The minute hand did not move at all. We waited and waited in the cold, but nothing happened. At that moment, someone shouted, \"It''s already past twelve — the clock has stopped!\" I looked at my watch, and it was true: the clock refused to welcome the New Year. Everybody began to laugh, and then we all started to sing.","explanation_cn":"课文说大钟差5分12点停摆、\"拒绝\"迎接新年,所以叫\"冷遇\"。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"What did the minute hand do?","options":["It fell off","It moved very fast","It did not move at all","It struck twelve"],"answer_index":2,"passage":"It was New Year''s Eve, and that year it fell on the weekend. On Saturday night, my friends and I went to the old Town Hall. A huge crowd gathered on the sidewalk under the big clock. People stood in a long line, waiting to welcome the New Year. The clock would strike twelve at midnight, in just a few minutes. But at five to twelve, the big clock suddenly stopped! The minute hand did not move at all. We waited and waited in the cold, but nothing happened. At that moment, someone shouted, \"It''s already past twelve — the clock has stopped!\" I looked at my watch, and it was true: the clock refused to welcome the New Year. Everybody began to laugh, and then we all started to sing.","explanation_cn":"课文说 The minute hand did not move at all,分针一动不动。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"Where did the crowd gather?","options":["Under the Town Hall clock","At the train station","At the airport","In a restaurant"],"answer_index":0,"audio":"It was New Year''s Eve, and that year it fell on the weekend. On Saturday night, my friends and I went to the old Town Hall. A huge crowd gathered on the sidewalk under the big clock. People stood in a long line, waiting to welcome the New Year. The clock would strike twelve at midnight, in just a few minutes. But at five to twelve, the big clock suddenly stopped! The minute hand did not move at all. We waited and waited in the cold, but nothing happened. At that moment, someone shouted, \"It''s already past twelve — the clock has stopped!\" I looked at my watch, and it was true: the clock refused to welcome the New Year. Everybody began to laugh, and then we all started to sing.","explanation_cn":"课文说 A huge crowd gathered… under the big clock,人群聚在市政厅大钟下面。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l09',10,NULL,'choice','{"stem":"How did people feel at the end?","options":["Bored and tired","Angry and upset","Happy — they laughed and sang","Scared"],"answer_index":2,"audio":"It was New Year''s Eve, and that year it fell on the weekend. On Saturday night, my friends and I went to the old Town Hall. A huge crowd gathered on the sidewalk under the big clock. People stood in a long line, waiting to welcome the New Year. The clock would strike twelve at midnight, in just a few minutes. But at five to twelve, the big clock suddenly stopped! The minute hand did not move at all. We waited and waited in the cold, but nothing happened. At that moment, someone shouted, \"It''s already past twelve — the clock has stopped!\" I looked at my watch, and it was true: the clock refused to welcome the New Year. Everybody began to laugh, and then we all started to sing.","explanation_cn":"课文结尾大家笑着唱起歌来,心情是高兴的。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l10',2,2,10,'Not for jazz','不适于演奏爵士乐','被动语态(主考:be+过去分词 · 一般现在/过去被动 · by · 主动↔被动转换 · 否定疑问)+ 名词所有格(辅考:''s/of属格/双重所有格)','家里一架古钢琴 · 被来访客人用力弹爵士乐弄断了弦 · 现在不许碰、正由父亲的朋友修理','{"q":"Listen and answer — What happened to the clavichord?","options":["It was damaged by a visitor","It was sold","It was lost","It was repainted"],"answer_index":0}'::jsonb,'{"title":"说\"某物被…\"(被动语态)","intro":"本课讲怎么说\"某物被别人怎么样了\"——被动语态。主角是动作的承受者。全用本课句子举例。","table":{"headers":["规则 / 构成","本课 / 常见例子"],"rows":[["被动语态 = be + 过去分词(主角是''被…的那一方'')","It was made in Germany.(古钢琴被造)"],["一般现在被动:am / is / are + 过去分词","The clavichord is kept in the living room."],["一般过去被动:was / were + 过去分词","Two of the strings were broken."],["要指出''谁做的'',用 by + 动作执行者","It was bought by my grandpa."],["主动变被动:原来的宾语挪到前面当主角,动词变 be + 过去分词","Workmen built the road. → The road was built by workmen."]]},"specialRules":[{"rule":"被动语态的时态靠改变 be 来体现,过去分词永远不变","mark":"时态看 be"},{"rule":"否定:be + not + 过去分词(are not allowed);疑问:把 be 提前(Was it made…?)","mark":"否定 / 疑问"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',1,NULL,'My family owns an old musical instrument called a clavichord.','我家有一件古老的乐器,叫古钢琴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',2,NULL,'It was made in Germany over three hundred years ago.','它是三百多年前在德国制造的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',3,NULL,'The clavichord is kept in our living room.','这架古钢琴摆放在我们的客厅里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',4,NULL,'It has belonged to my family for generations.','它在我家已经传了好几代。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',5,NULL,'It was bought by my grandpa a long time ago.','它是我爷爷很久以前买下的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',6,NULL,'Recently, it was damaged by a visitor.','最近,它被一位来访的客人弄坏了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',7,NULL,'She wanted to practice jazz on it and struck the keys too hard.','她想用它练爵士乐,击键时用力过猛。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l10',8,NULL,'Two of the strings were broken, and my dad was shocked.','两根弦断了,我爸爸大为吃惊。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
